fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  sisu, -- märgistatud veerg
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
päring: SELECT rowid FROM messages_fts WHERE sisu MATCH 'foo'

